import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import api from '@/lib/axios'
import { useAuth } from '@/stores/auth'
import type { LoginInput, RegisterInput, User } from '@/types/schemas'

interface AuthResponse {
  user: User
}

async function fetchCsrfToken(): Promise<string> {
  const { data } = await api.get<{ csrfToken: string }>('/auth/csrf-token')
  return data.csrfToken
}

export function useLogin() {
  const { setUser } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (input: LoginInput) => {
      const { data } = await api.post<AuthResponse>('/auth/login', input)
      return data.user
    },
    onSuccess: (user) => {
      setUser(user)
      queryClient.invalidateQueries({ queryKey: ['me'] })
    },
  })
}

export function useRegister() {
  const { setUser } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (input: RegisterInput) => {
      const { data } = await api.post<AuthResponse>('/auth/register', input)
      return data.user
    },
    onSuccess: (user) => {
      setUser(user)
      queryClient.invalidateQueries({ queryKey: ['me'] })
    },
  })
}

export function useLogout() {
  const { clearUser } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async () => {
      const { data } = await api.post<{ ok: boolean }>('/auth/logout')
      return data.ok
    },
    onSuccess: () => {
      clearUser()
      queryClient.removeQueries({ queryKey: ['me'] })
    },
  })
}

export function useMe() {
  const { setUser } = useAuth()

  return useQuery({
    queryKey: ['me'],
    queryFn: async () => {
      const { data } = await api.get<{ user: User | null }>('/auth/me')
      if (data.user) setUser(data.user)
      return data.user
    },
    retry: false,
    staleTime: 5 * 60 * 1000,
  })
}
